const { today } = $('Konu Kategorisi Belirle').first().json;
const raw = $input.first().json.choices[0].message.content.trim();
const jsonStr = raw.replace(/^```json?\n?/, '').replace(/\n?```$/, '').trim();
function sanitize(s) {
  return s.replace(/"(?:[^"\\]|\\.)*"/g, m => m.replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t'));
}
let post;
try { post = JSON.parse(sanitize(jsonStr)); } catch(e) { throw new Error('Groq parse error: ' + e.message + ' | Raw: ' + raw.slice(0, 300)); }
const fm = '---\ntitle: "' + post.title.replace(/"/g, '\\"') + '"\ndescription: "' + post.description.replace(/"/g, '\\"') + '"\npublishDate: "' + today + '"\ntags: [' + post.tags.map(t => '"' + t + '"').join(', ') + ']\ndraft: false\n---\n\n';
const markdown = fm + post.content;
const filePath = 'src/content/blog/' + post.slug + '.md';
const content = Buffer.from(markdown, 'utf8').toString('base64');
return [{ json: { filePath, content, title: post.title, slug: post.slug } }];
